// ---------------------------------------------------------------------------
// Multi-LLM Free-Tier Gateway engine
// Cascading fallback across free-tier providers -- if one is rate-limited or
// erroring, the next one picks up the request automatically.
// ---------------------------------------------------------------------------

const input = $input.first().json;
const body = input.body || input;

const message = body.message;
const mode = (body.mode || 'auto').toLowerCase();
const requestedModel = body.model;
const requestedModels = body.models;

if (!message || typeof message !== 'string') {
  return [{ json: { error: 'message (string) is required', statusCode: 400 } }];
}

// ---------------------------------------------------------------------------
// Provider registry -- every entry here is a FREE tier, all hosted (no local
// server required). Ordered = fallback priority for 'auto' and 'fallback'
// modes.
// ---------------------------------------------------------------------------
const PROVIDERS = [
  {
    id: 'groq-llama-3.3-70b',
    provider: 'groq',
    envKey: 'GROQ_API_KEY',
    call: async (msg) => {
      const key = $env.GROQ_API_KEY;
      if (!key) throw new Error('GROQ_API_KEY not set');
      const res = await this.helpers.httpRequest({
        method: 'POST',
        url: 'https://api.groq.com/openai/v1/chat/completions',
        headers: { Authorization: `Bearer ${key}`, 'Content-Type': 'application/json' },
        body: { model: 'llama-3.3-70b-versatile', messages: [{ role: 'user', content: msg }] },
        json: true,
        timeout: 30000,
      });
      return res.choices[0].message.content;
    },
  },
  {
    id: 'cerebras-llama3.1-8b',
    provider: 'cerebras',
    envKey: 'CEREBRAS_API_KEY',
    call: async (msg) => {
      const key = $env.CEREBRAS_API_KEY;
      if (!key) throw new Error('CEREBRAS_API_KEY not set');
      const res = await this.helpers.httpRequest({
        method: 'POST',
        url: 'https://api.cerebras.ai/v1/chat/completions',
        headers: { Authorization: `Bearer ${key}`, 'Content-Type': 'application/json' },
        body: { model: 'llama3.1-8b', messages: [{ role: 'user', content: msg }] },
        json: true,
        timeout: 30000,
      });
      return res.choices[0].message.content;
    },
  },
  {
    id: 'openrouter-llama3.3-70b-free',
    provider: 'openrouter',
    envKey: 'OPENROUTER_API_KEY',
    call: async (msg) => {
      const key = $env.OPENROUTER_API_KEY;
      if (!key) throw new Error('OPENROUTER_API_KEY not set');
      const res = await this.helpers.httpRequest({
        method: 'POST',
        url: 'https://openrouter.ai/api/v1/chat/completions',
        headers: { Authorization: `Bearer ${key}`, 'Content-Type': 'application/json' },
        body: { model: 'meta-llama/llama-3.3-70b-instruct:free', messages: [{ role: 'user', content: msg }] },
        json: true,
        timeout: 30000,
      });
      return res.choices[0].message.content;
    },
  },
  {
    id: 'gemini-1.5-flash',
    provider: 'gemini',
    envKey: 'GOOGLE_API_KEY',
    call: async (msg) => {
      const key = $env.GOOGLE_API_KEY;
      if (!key) throw new Error('GOOGLE_API_KEY not set');
      const res = await this.helpers.httpRequest({
        method: 'POST',
        url: `https://generativelanguage.googleapis.com/v1beta/models/gemini-1.5-flash:generateContent?key=${key}`,
        headers: { 'Content-Type': 'application/json' },
        body: { contents: [{ parts: [{ text: msg }] }] },
        json: true,
        timeout: 30000,
      });
      return res.candidates[0].content.parts[0].text;
    },
  },
  {
    id: 'mistral-small',
    provider: 'mistral',
    envKey: 'MISTRAL_API_KEY',
    call: async (msg) => {
      const key = $env.MISTRAL_API_KEY;
      if (!key) throw new Error('MISTRAL_API_KEY not set');
      const res = await this.helpers.httpRequest({
        method: 'POST',
        url: 'https://api.mistral.ai/v1/chat/completions',
        headers: { Authorization: `Bearer ${key}`, 'Content-Type': 'application/json' },
        body: { model: 'mistral-small-latest', messages: [{ role: 'user', content: msg }] },
        json: true,
        timeout: 30000,
      });
      return res.choices[0].message.content;
    },
  },
  {
    id: 'cohere-command-r',
    provider: 'cohere',
    envKey: 'COHERE_API_KEY',
    call: async (msg) => {
      const key = $env.COHERE_API_KEY;
      if (!key) throw new Error('COHERE_API_KEY not set');
      const res = await this.helpers.httpRequest({
        method: 'POST',
        url: 'https://api.cohere.com/v1/chat',
        headers: { Authorization: `Bearer ${key}`, 'Content-Type': 'application/json' },
        body: { model: 'command-r', message: msg },
        json: true,
        timeout: 30000,
      });
      return res.text;
    },
  },
  {
    id: 'github-gpt-4o-mini',
    provider: 'github-models',
    envKey: 'GITHUB_TOKEN',
    call: async (msg) => {
      const key = $env.GITHUB_TOKEN;
      if (!key) throw new Error('GITHUB_TOKEN not set');
      const res = await this.helpers.httpRequest({
        method: 'POST',
        url: 'https://models.inference.ai.azure.com/chat/completions',
        headers: { Authorization: `Bearer ${key}`, 'Content-Type': 'application/json' },
        body: { model: 'gpt-4o-mini', messages: [{ role: 'user', content: msg }] },
        json: true,
        timeout: 30000,
      });
      return res.choices[0].message.content;
    },
  },
  {
    id: 'sambanova-llama3.1-8b',
    provider: 'sambanova',
    envKey: 'SAMBANOVA_API_KEY',
    call: async (msg) => {
      const key = $env.SAMBANOVA_API_KEY;
      if (!key) throw new Error('SAMBANOVA_API_KEY not set');
      const res = await this.helpers.httpRequest({
        method: 'POST',
        url: 'https://api.sambanova.ai/v1/chat/completions',
        headers: { Authorization: `Bearer ${key}`, 'Content-Type': 'application/json' },
        body: { model: 'Meta-Llama-3.1-8B-Instruct', messages: [{ role: 'user', content: msg }] },
        json: true,
        timeout: 30000,
      });
      return res.choices[0].message.content;
    },
  },
  {
    id: 'hf-mistral-7b',
    provider: 'huggingface',
    envKey: 'HF_API_KEY',
    call: async (msg) => {
      const key = $env.HF_API_KEY;
      if (!key) throw new Error('HF_API_KEY not set');
      const res = await this.helpers.httpRequest({
        method: 'POST',
        url: 'https://api-inference.huggingface.co/models/mistralai/Mistral-7B-Instruct-v0.3',
        headers: { Authorization: `Bearer ${key}`, 'Content-Type': 'application/json' },
        body: { inputs: msg },
        json: true,
        timeout: 30000,
      });
      return Array.isArray(res) ? res[0].generated_text : res.generated_text;
    },
  },
];

// ---------------------------------------------------------------------------
// Sensitivity classifier -- crude keyword check. Flags likely PII/sensitive
// content in the response so the caller can decide how to handle it. No
// local fallback exists on n8n Cloud, so this does not change routing.
// ---------------------------------------------------------------------------
function classify(msg) {
  const flags = ['ssn', 'bvn', 'nin', 'password', 'passport', 'salary', 'medical', 'diagnosis', 'bank account', 'credit card'];
  const lower = msg.toLowerCase();
  return flags.some((f) => lower.includes(f)) ? 'sensitive' : 'general';
}

async function runOne(entry, msg) {
  try {
    const text = await entry.call.call(this, msg);
    return { model: entry.id, provider: entry.provider, tier: 'free', text, error: null };
  } catch (err) {
    return { model: entry.id, provider: entry.provider, tier: 'free', text: null, error: err.message || String(err) };
  }
}

async function cascade(msg, chain) {
  const attempts = [];
  for (const entry of chain) {
    const result = await runOne.call(this, entry, msg);
    attempts.push(result);
    if (result.text) {
      return { text: result.text, results: attempts, usedModel: entry.id };
    }
  }
  return { text: null, results: attempts, usedModel: null };
}

let output;
const classification = classify(message);

if (mode === 'manual') {
  const entry = PROVIDERS.find((p) => p.id === requestedModel);
  if (entry) {
    const result = await runOne.call(this, entry, message);
    if (result.text) {
      output = { source: 'manual', text: result.text, results: [result], mode, classification };
    } else {
      // requested model failed -- cascade through the rest as fallback
      const rest = PROVIDERS.filter((p) => p.id !== entry.id);
      const cascaded = await cascade.call(this, message, rest);
      output = { source: 'manual-fallback', text: cascaded.text, results: [result, ...cascaded.results], mode, classification };
    }
  } else {
    // unknown model id -- fall through the standard chain
    const cascaded = await cascade.call(this, message, PROVIDERS);
    output = { source: 'manual-unknown-model', text: cascaded.text, results: cascaded.results, mode, classification };
  }
} else if (mode === 'fanout') {
  const chain = requestedModels && requestedModels.length
    ? PROVIDERS.filter((p) => requestedModels.includes(p.id))
    : PROVIDERS;
  const results = await Promise.all(chain.map((entry) => runOne.call(this, entry, message)));
  output = { source: 'fanout', text: (results.find((r) => r.text) || {}).text || null, results, mode, classification };
} else if (mode === 'fallback') {
  const cascaded = await cascade.call(this, message, PROVIDERS);
  output = { source: 'fallback', text: cascaded.text, results: cascaded.results, mode, classification };
} else {
  // 'auto' (default): n8n Cloud has no local/self-hosted fallback, so
  // sensitive content still goes through the normal chain -- it's just
  // flagged in the response so the caller knows to handle it carefully.
  const cascaded = await cascade.call(this, message, PROVIDERS);
  output = { source: 'auto', text: cascaded.text, results: cascaded.results, mode, classification };
  if (classification === 'sensitive') {
    output.warning = 'message flagged as sensitive but sent to hosted free-tier providers (no local fallback available on n8n Cloud)';
  }
}

if (!output.text) {
  return [{
    json: { ...output, error: 'all providers in the chain failed or are unconfigured', statusCode: 502 },
  }];
}

return [{ json: { ...output, output: output.text, statusCode: 200 } }];
